command:
$ErrorActionPreference='Stop';
git fetch origin --prune;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$branch=(git branch --show-current).Trim();
if($branch -ne 'main'){throw "Expected main branch, found $branch"};
$head=(git rev-parse HEAD).Trim();
$origin=(git rev-parse origin/main).Trim();
Write-Output "HEAD=$head";
Write-Output "ORIGIN_MAIN=$origin";
if($head -ne $origin){throw "origin/main moved; refusing to commit on stale main"};
git diff --check;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
Write-Output 'STATUS_BEFORE_STAGE';
git status --short;
Write-Output 'DIFF_STAT';
git diff --stat;
$paths=@(
'app/winui/MainWindow.xaml.cpp',
'app/winui/file_detail_controller.cpp',
'app/winui/file_list_state.h',
'app/winui/helper/FlyShellIsolationHelper.cpp',
'src/base/shell_assoc_type_core.cpp',
'src/base/shell_assoc_type_core.h',
'tests/winui/test_known_folder_artwork_contract.py'
);
git add -- $paths;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
git diff --cached --check;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$unstaged=@(git diff --name-only);
$untracked=@(git ls-files --others --exclude-standard);
if($unstaged.Count -ne 0 -or $untracked.Count -ne 0){
  Write-Output 'UNEXPECTED_REMAINDER';
  $unstaged | ForEach-Object { Write-Output "UNSTAGED $_" };
  $untracked | ForEach-Object { Write-Output "UNTRACKED $_" };
  throw 'Unexpected worktree remainder after staging exact Known Folder scope';
}
Write-Output 'STAGED_STAT';
git diff --cached --stat;
Write-Output 'STAGED_FILES';
git diff --cached --name-only;
git commit -m "ui: add Known Folder artwork";
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$newHead=(git rev-parse HEAD).Trim();
Write-Output "PRODUCT_COMMIT=$newHead";
git push origin main;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
git fetch origin --prune;
$after=(git rev-parse origin/main).Trim();
if($newHead -ne $after){throw "Pushed commit does not match origin/main"};
$counts=(git rev-list --left-right --count HEAD...origin/main).Trim();
Write-Output "AHEAD_BEHIND=$counts";
Write-Output 'STATUS_AFTER_PUSH';
git status --short;
